def register_existing_documents(apps, schema_editor):
    """The attachments of submissions stored before documents were kept, so they are downloaded too."""
    import os

    KoboSubmission = apps.get_model("msr_etl", "KoboSubmission")
    ApplicantDocument = apps.get_model("msr_etl", "ApplicantDocument")
    documents = []
    for submission in KoboSubmission.objects.all().iterator():
        for attachment in (submission.data or {}).get("_attachments") or []:
            if attachment.get("is_deleted") or not attachment.get("uid"):
                continue
            question = str(attachment.get("question_xpath") or "")
            name = attachment.get("media_file_basename") or os.path.basename(str(attachment.get("filename") or ""))
            documents.append(ApplicantDocument(
                submission_id=submission.id, individual_id=submission.individual_id,
                kobo_attachment_uid=str(attachment["uid"]), question=question,
                document_type=question.split("/")[-1], filename=str(name)[:255],
                mimetype=str(attachment.get("mimetype") or ""),
            ))
    ApplicantDocument.objects.bulk_create(documents, ignore_conflicts=True, batch_size=500)


